import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY = 1024 * 1024;
const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

type FieldError = { field: string; message: string };

class HttpError extends Error {
  constructor(
    public status: number,
    public code: string,
    message: string,
    public fields?: FieldError[],
  ) {
    super(message);
  }
}

function send(res: ServerResponse, status: number, body: unknown): void {
  const data = JSON.stringify(body);
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'content-length': Buffer.byteLength(data) });
  res.end(data);
}

function sendError(res: ServerResponse, err: HttpError): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.fields) error.fields = err.fields;
  else if (err.code === 'invalid_request') error.fields = [];
  send(res, err.status, { error });
}

function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooBig = false;
    req.on('data', (c: Buffer) => {
      size += c.length;
      if (size > MAX_BODY) tooBig = true;
      else chunks.push(c);
    });
    req.on('end', () => resolve(tooBig ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

const stmtGet = db.prepare('SELECT * FROM jobs WHERE id = ?');
const stmtList = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const stmtByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const stmtInsert = db.prepare(`INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, run_after, idempotency_key, payload, created_at, updated_at)
  VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?, ?, ?)`);
const stmtHeartbeat = db.prepare("SELECT at FROM heartbeat WHERE name = 'worker'");

interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

function validate(body: unknown, fields: FieldError[]): Payload | null {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    fields.push({ field: 'body', message: 'Body must be a JSON object.' });
    return null;
  }
  const obj = body as Record<string, unknown>;
  const allowed = new Set(['input', 'steps', 'failAttempts']);
  for (const k of Object.keys(obj)) {
    if (!allowed.has(k)) fields.push({ field: k, message: 'Unknown field.' });
  }
  const input = obj.input;
  if (input === undefined) fields.push({ field: 'input', message: 'input is required.' });
  else if (typeof input !== 'string') fields.push({ field: 'input', message: 'input must be a string.' });
  else if (input.length < 1 || input.length > 1000) fields.push({ field: 'input', message: 'input must be 1-1000 characters.' });
  else if (input.trim() === '') fields.push({ field: 'input', message: 'input must not be only whitespace.' });

  const intField = (name: string, min: number, max: number, def: number): number => {
    const v = obj[name];
    if (v === undefined) return def;
    if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
      fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}.` });
      return def;
    }
    return v;
  };
  const steps = intField('steps', 1, 20, 5);
  const failAttempts = intField('failAttempts', 0, 5, 0);
  if (fields.length) return null;
  return { input: input as string, steps, failAttempts };
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];
  const rawKey = req.headers['idempotency-key'];
  let key: string | null = null;
  if (rawKey !== undefined) {
    const k = Array.isArray(rawKey) ? rawKey.join(',') : rawKey;
    if (!KEY_RE.test(k)) fields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$.' });
    else key = k;
  }
  const ct = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  const isJson = ct === 'application/json' || /^application\/[a-z0-9.+-]*\+json$/.test(ct);
  const raw = await readBody(req);
  let payload: Payload | null = null;
  if (!isJson) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
  } else if (raw === null) {
    fields.push({ field: 'body', message: 'Body is too large.' });
  } else {
    let parsed: unknown;
    let ok = true;
    try {
      parsed = JSON.parse(raw);
    } catch {
      ok = false;
      fields.push({ field: 'body', message: 'Body must be valid JSON.' });
    }
    if (ok) payload = validate(parsed, fields);
  }
  if (fields.length || !payload) {
    throw new HttpError(400, 'invalid_request', 'The request is invalid.', fields);
  }
  const payloadJson = JSON.stringify([payload.input, payload.steps, payload.failAttempts]);

  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== null) {
      const existing = stmtByKey.get(key) as (JobRow & { payload: string }) | undefined;
      if (existing) {
        db.exec('COMMIT');
        if (existing.payload === payloadJson) return send(res, 200, toJob(existing));
        throw new HttpError(409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload.');
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    stmtInsert.run(id, payload.input, payload.steps, payload.failAttempts, key, payloadJson, now, now);
    const row = stmtGet.get(id) as unknown as JobRow;
    db.exec('COMMIT');
    send(res, 201, toJob(row));
  } catch (e) {
    if (db.isTransaction) db.exec('ROLLBACK');
    throw e;
  }
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const allow = (methods: string[]) => {
    if (!methods.includes(method)) {
      res.setHeader('allow', methods.join(', '));
      throw new HttpError(405, 'method_not_allowed', `Method ${method} not allowed.`);
    }
  };

  if (pathname === '/') {
    allow(['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/health') {
    allow(['GET']);
    const hb = stmtHeartbeat.get() as { at: number } | undefined;
    const up = !!hb && Date.now() - hb.at < 3000;
    return send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    allow(['GET', 'POST']);
    if (method === 'POST') return createJob(req, res);
    const rows = stmtList.all() as unknown as JobRow[];
    return send(res, 200, { jobs: rows.map(toJob) });
  }
  const m = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (m) {
    allow(['GET']);
    let id: string;
    try {
      id = decodeURIComponent(m[1]!);
    } catch {
      throw new HttpError(404, 'not_found', 'Job not found.');
    }
    const row = stmtGet.get(id) as JobRow | undefined;
    if (!row) throw new HttpError(404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
  throw new HttpError(404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    if (res.headersSent) return void res.end();
    if (err instanceof HttpError) return sendError(res, err);
    console.error(err);
    sendError(res, new HttpError(500, 'internal_error', 'Internal server error.'));
  });
});
server.listen(port, () => console.log(`server listening on ${port}`));

let closing = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    if (closing) return;
    closing = true;
    server.close(() => {
      db.close();
      process.exit(0);
    });
    server.closeAllConnections();
    setTimeout(() => process.exit(0), 3000).unref();
  });
}

